{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Renewed Balance in Three Phases</title>
  <meta name="description" content="Integrative, personalized planning for sustainable wellbeing. Evidence-aware guidance and a clear three-phase planner.">
  <link rel="preload" href="assets/css/styles.css" as="style">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="glass-bg">
  <header class="nav-wrap">
    <div class="container nav-inner">
      <a href="/" class="brand">
        <svg width="36" height="36" viewBox="0 0 100 100" aria-hidden="true">
          <rect x="10" y="10" width="80" height="80" rx="18" fill="none" stroke="#fff" stroke-opacity="0.14" stroke-width="4"/>
          <circle cx="50" cy="36" r="10" fill="#fff" fill-opacity="0.14"/>
          <path d="M30 66c8-10 20-12 40-6" fill="none" stroke="#fff" stroke-opacity="0.12" stroke-width="4"/>
        </svg>
        <span class="brand-text">{{BUSINESS_NAME}}</span>
      </a>
      <nav class="main-nav">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Conditions</a>
        <a href="/approach.html">Method</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">Team</a>
        <a href="/book.html" class="btn-ghost">Book</a>
        <a href="/contact.html" class="btn-primary">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="menu-toggle" aria-label="menu">☰</button>
    </div>
  </header>

  <main>
    <section class="hero container">
      <div class="hero-inner">
        <div class="hero-copy">
          <h1>Reconnect energy, priorities, and routine with a clear three-stage plan</h1>
          <p class="lead">A practical integrative approach to restore balance — personalized teaching, measurable short steps, and periodic reassessment.</p>
          <div class="hero-ctas">
            <a class="btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn-ghost" href="/services.html">Explore Offerings</a>
          </div>
          <ul class="meta-list">
            <li>Virtual & in-person in {{CITY}}, {{STATE}}</li>
            <li>Phone: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
          </ul>
        </div>
        <div class="hero-aside">
          <div class="card glass-card proof-rotor" aria-live="polite">
            <div class="badge-strip">
              <span class="cred-badge" data-tip="Board certified clinicians and licensed practitioners">LIC</span>
              <span class="cred-badge" data-tip="Published case summaries & community talks">EVIDENCE</span>
              <span class="cred-badge" data-tip="Secure telehealth, HIPAA-aligned">SECURE</span>
            </div>
            <div class="testimonial">
              <blockquote id="testimonial-text">"My coach helped me take pressure off and actually feel progress — step by step."</blockquote>
              <cite id="testimonial-author">— A. Walker</cite>
            </div>
            <div class="rotor-controls">
              <button id="rotor-prev" aria-label="previous">◀</button>
              <div id="rotor-dots" class="dots"></div>
              <button id="rotor-next" aria-label="next">▶</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="social-proof container">
      <h2>Evidence of steady change</h2>
      <p class="kicker">Short case snapshots and alliance indicators — what people notice when things shift.</p>
      <div class="proof-gallery">
        <div class="badges">
          <div class="badge" data-tip="Peer-reviewed summaries"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="#fff" stroke-opacity="0.14" stroke-width="1.5"/></svg><span>Summaries</span></div>
          <div class="badge" data-tip="Community education series"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3" fill="none" stroke="#fff" stroke-opacity="0.14" stroke-width="1.5"/></svg><span>Series</span></div>
          <div class="badge" data-tip="Licensed mental health & nutrition specialists"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h16" fill="none" stroke="#fff" stroke-opacity="0.14" stroke-width="1.5"/></svg><span>Team</span></div>
        </div>
        <div class="testimonials-rotor" id="gallery-rotor">
          <!-- JS injects rotating testimonials here -->
        </div>
      </div>
    </section>

    <section class="benefits container">
      <h2>What we guide you toward</h2>
      <ul class="benefit-grid">
        <li><strong>Orderable steps.</strong> Small habits you can try and track without disruption.
        </li>
        <li><strong>Clarity of choice.</strong> Decide what to prioritize this quarter, with clinician coaching.
        </li>
        <li><strong>Sensibility not haste.</strong> Practice-backed options framed as experiments, not promises.
        </li>
      </ul>
    </section>

    <section class="process container" id="timeline-section">
      <h2>Roadmap planner: a three-phase outline</h2>
      <p class="muted">Use the planner to build a personalized roadmap. Phases are educational and supportive; outcomes vary.</p>
      <div class="timeline">
        <div class="phase" data-phase="1">
          <h3>Phase 1 — Stabilize</h3>
          <p>Short checks, baseline measures, and immediate self-care strategies to stop momentum loss.</p>
          <label>Duration (weeks)
            <input type="range" min="2" max="8" value="4" class="range-input" data-target="weeks-1">
          </label>
          <div class="indicator">Planned: <span id="weeks-1">4</span> weeks</div>
        </div>
        <div class="phase" data-phase="2">
          <h3>Phase 2 — Build Skills</h3>
          <p>Learning practical strategies tailored to your day: movement, sleep patterns, and mindful routines.</p>
          <label>Sessions per month
            <input type="range" min="1" max="6" value="3" class="range-input" data-target="sessions-2">
          </label>
          <div class="indicator">Planned: <span id="sessions-2">3</span> sessions / month</div>
        </div>
        <div class="phase" data-phase="3">
          <h3>Phase 3 — Sustain</h3>
          <p>Transition to self-managed rhythm, periodic check-ins, and community resources to reinforce gains.</p>
          <label>Check-in frequency
            <input type="range" min="1" max="12" value="3" class="range-input" data-target="checkins-3">
          </label>
          <div class="indicator">Planned: <span id="checkins-3">3</span> months between check-ins</div>
        </div>
      </div>
      <div class="planner-summary">
        <p><strong>Summary:</strong> <span id="planner-summary-text">Phase 1: 4 weeks • Phase 2: 3 sessions/month • Phase 3: 3 months</span></p>
        <p class="disclaimer">Disclaimer: This planner is educational and not medical advice. Individual needs and timelines differ; consult your clinical team for formal guidance.</p>
        <a href="/book.html" class="btn-primary">Plan a roadmap session</a>
      </div>
    </section>

    <section class="faq container">
      <h2>Common questions</h2>
      <details>
        <summary>How does the first visit work?</summary>
        <p>We take a focused review of your priorities, gather baseline measures, and co-create short experiments to try between sessions.</p>
      </details>
      <details>
        <summary>Do you replace medical care?</summary>
        <p>We provide educational guidance and supportive planning and do not replace primary or specialty medical care. For urgent issues, seek immediate medical attention.</p>
      </details>
    </section>

    <section class="cta container">
      <div class="cta-inner">
        <h2>Ready to map the next three months?</h2>
        <p>Book a focused planning day for concentrated guidance — an intensive, collaborative session with deliverables you can use immediately.</p>
        <a class="btn-primary large" href="/book.html">Reserve a planning day</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</p>
      </div>
      <nav class="footer-nav">
        <a href="/about.html">About</a>
        <a href="/services.html">Offerings</a>
        <a href="/contact.html">Contact</a>
        <a href="/privacy.html">Privacy</a>
      </nav>
    </div>
  </footer>

  <svg class="page-pattern" width="0" height="0" aria-hidden="true" focusable="false">
    <defs>
      <pattern id="svgPattern" patternUnits="userSpaceOnUse" width="120" height="120">
        <rect width="120" height="120" fill="url(#p)" />
      </pattern>
    </defs>
  </svg>

  <div id="tooltip" role="status" aria-live="polite"></div>
</body>
</html>"} 
