{"path":"assets/css/styles.css","content":"/* Glass morphism theme for integrative planning */
:root{
  --bg:#0f1724;
  --glass: rgba(255,255,255,0.06);
  --glass-2: rgba(255,255,255,0.04);
  --accent:#9ad3c6;
  --muted:#b7c3cc;
  --card:#ffffff08;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg); color:#e6eef3; -webkit-font-smoothing:antialiased}
.container{max-width:1100px;margin:0 auto;padding:28px}
.nav-wrap{backdrop-filter: blur(8px);background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border-bottom:1px solid rgba(255,255,255,0.03)}
.nav-inner{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:inherit}
.brand-text{font-weight:700}
.main-nav{display:flex;gap:12px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.btn-primary{background:linear-gradient(90deg,var(--accent),#7bd3b2);color:#062226}
.menu-toggle{display:none;background:none;border:0;color:var(--muted);font-size:20px}
.hero{padding-top:48px;padding-bottom:48px}
.hero-inner{display:flex;gap:28px;align-items:stretch}
.hero-copy{flex:1}
.hero-aside{width:320px}
.lead{color:var(--muted);margin-top:8px}
.btn-primary{background:linear-gradient(90deg,var(--accent),#7bd3b2);color:#062226;padding:12px 16px;border-radius:12px;text-decoration:none;font-weight:600}
.btn-primary.large{padding:16px 22px;font-size:18px}
.btn-ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:10px 14px;border-radius:10px;color:var(--muted);text-decoration:none}
.meta-list{list-style:none;padding:0;margin:12px 0;color:var(--muted)}
.glass-card{background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.02));border-radius:14px;padding:16px;backdrop-filter: blur(6px);border:1px solid rgba(255,255,255,0.04)}
.badge-strip{display:flex;gap:8px;margin-bottom:10px}
.cred-badge{background:rgba(255,255,255,0.02);padding:6px 8px;border-radius:8px;font-weight:700;color:var(--muted);font-size:12px}
.testimonial{padding:8px}
.testimonial blockquote{margin:0;color:#eaf7f1;font-weight:600}
.testimonial cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.rotor-controls{display:flex;align-items:center;gap:8px;margin-top:12px}
.rotor-controls button{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:6px 8px;border-radius:8px}
.dots{display:flex;gap:6px}
.dots button{background:rgba(255,255,255,0.03);border:0;width:8px;height:8px;border-radius:50%}
.social-proof{padding-top:36px;padding-bottom:36px}
.proof-gallery{display:flex;gap:20px;align-items:flex-start}
.proof-gallery .badges{display:flex;flex-direction:column;gap:10px}
.badge{display:flex;gap:8px;align-items:center;padding:10px;border-radius:10px;background:var(--card);cursor:pointer}
.badge svg{width:28px;height:28px}
.testimonials-rotor{flex:1;background:linear-gradient(180deg, rgba(0,0,0,0.04), rgba(255,255,255,0.02));padding:16px;border-radius:12px}
.benefits{padding-top:10px;padding-bottom:10px}
.benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;list-style:none;padding:0}
.benefit-grid li{background:var(--card);padding:14px;border-radius:10px;color:var(--muted)}
.process .timeline{display:flex;gap:12px;margin-top:14px}
.phase{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);flex:1}
.range-input{width:100%;margin-top:8px}
.indicator{color:var(--muted);margin-top:6px;font-size:13px}
.planner-summary{margin-top:14px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03)}
.disclaimer{font-size:12px;color:var(--muted);margin-top:8px}
.faq details{background:var(--card);padding:12px;border-radius:10px;margin-top:8px}
.site-footer{padding:20px;background:linear-gradient(0deg, rgba(255,255,255,0.01), transparent);border-top:1px solid rgba(255,255,255,0.03);margin-top:40px}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.footer-nav a{color:var(--muted);text-decoration:none;margin-left:10px}
.page-pattern{display:none}
#tooltip{position:fixed;pointer-events:none;z-index:60;min-width:120px;background:#061617;color:#dff6ef;padding:8px;border-radius:8px;font-size:13px;opacity:0;transform:translateY(6px);transition:opacity 160ms, transform 160ms}
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-aside{width:100%}
  .main-nav{display:none}
  .menu-toggle{display:block}
  .benefit-grid{grid-template-columns:1fr}
  .process .timeline{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Testimonials and badges rotation + tooltip
  const testimonials = [
    {text: '"I finally had a plan that fit my week and my work demands.' , author: '— R. Chen'},
    {text: '"Concrete experiments helped me sleep better within a month.' , author: '— S. Patel'},
    {text: '"The team listens and then offers small, doable shifts.' , author: '— J. Morgan'}
  ];

  const rotorText = document.getElementById('testimonial-text');
  const rotorAuthor = document.getElementById('testimonial-author');
  const prevBtn = document.getElementById('rotor-prev');
  const nextBtn = document.getElementById('rotor-next');
  const dotsWrap = document.getElementById('rotor-dots');
  let idx = 0;
  let rotorTimer;

  function renderDots(){
    dotsWrap.innerHTML = '';
    testimonials.forEach((_,i)=>{
      const b = document.createElement('button');
      b.addEventListener('click', ()=>{ goTo(i); });
      if(i===0) b.style.background = '#7bd3b2';
      dotsWrap.appendChild(b);
    });
  }

  function updateRotor(){
    rotorText.textContent = testimonials[idx].text;
    rotorAuthor.textContent = testimonials[idx].author;
    Array.from(dotsWrap.children).forEach((d,i)=>{ d.style.background = i===idx? '#7bd3b2':'rgba(255,255,255,0.03)'; });
  }

  function next(){ idx = (idx+1) % testimonials.length; updateRotor(); }
  function prev(){ idx = (idx-1 + testimonials.length) % testimonials.length; updateRotor(); }
  function goTo(i){ idx = i; updateRotor(); }

  prevBtn.addEventListener('click', ()=>{ prev(); resetTimer(); });
  nextBtn.addEventListener('click', ()=>{ next(); resetTimer(); });

  function resetTimer(){ clearInterval(rotorTimer); rotorTimer = setInterval(next, 6000); }

  if(rotorText){ renderDots(); updateRotor(); rotorTimer = setInterval(next, 6000); }

  // Populate proof gallery rotor area
  const gallery = document.getElementById('gallery-rotor');
  if(gallery){
    const list = document.createElement('div');
    list.className = 'gallery-list';
    testimonials.forEach(t=>{
      const card = document.createElement('div');
      card.className = 'glass-card';
      const q = document.createElement('blockquote'); q.textContent = t.text; q.style.margin='0';
      const c = document.createElement('cite'); c.textContent = t.author; c.style.display='block'; c.style.marginTop='8px'; c.style.color='#bcdad1';
      card.appendChild(q); card.appendChild(c);
      list.appendChild(card);
    });
    gallery.appendChild(list);
  }

  // Tooltip for badges
  const tooltip = document.getElementById('tooltip');
  document.querySelectorAll('[data-tip]').forEach(el=>{
    el.addEventListener('mousemove', (e)=>{
      tooltip.style.left = (e.clientX + 12) + 'px';
      tooltip.style.top = (e.clientY + 12) + 'px';
      tooltip.textContent = el.getAttribute('data-tip');
      tooltip.style.opacity = '1';
      tooltip.style.transform = 'translateY(0)';
    });
    el.addEventListener('mouseleave', ()=>{ tooltip.style.opacity = '0'; });
  });

  // Timeline planner controls
  const ranges = document.querySelectorAll('.range-input');
  function syncRange(r){
    const target = r.dataset.target;
    const out = document.getElementById(target);
    if(out){ out.textContent = r.value; }
    // Update summary
    const weeks = document.getElementById('weeks-1').textContent;
    const sessions = document.getElementById('sessions-2').textContent;
    const checkins = document.getElementById('checkins-3').textContent;
    const sum = `Phase 1: ${weeks} weeks • Phase 2: ${sessions} sessions/month • Phase 3: ${checkins} months`;
    document.getElementById('planner-summary-text').textContent = sum;
  }
  ranges.forEach(r=>{ r.addEventListener('input', ()=>{ syncRange(r); }); syncRange(r); });

  // Simple mobile nav toggle
  const menuBtn = document.querySelector('.menu-toggle');
  const mainNav = document.querySelector('.main-nav');
  menuBtn && menuBtn.addEventListener('click', ()=>{ if(mainNav.style.display==='flex') mainNav.style.display='none'; else mainNav.style.display='flex'; });

  // Accessibility: reduce motion respect
  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(prefersReduced){ clearInterval(rotorTimer); }
})();
"} 
